contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run simulates calls from this test contract to c. We take no parameters
    // except an initial deposit amount to set up nonzero balance, and a flag
    // whether to attempt withdraw afterwards.
    function run(uint depositAmount, bool doWithdraw) public payable {
        require(address(this).balance >= depositAmount);

        // Ensure initial observed balance for this contract with respect to c
        uint beforeUserBal = c.getBalance(address(this));
        uint beforeCBalance = address(c).balance;

        // If depositAmount > 0, try to add to balance of this (InvMutTest) in c.
        if (depositAmount > 0) {
            // top-level state-changing call
            c.addToBalance{value: depositAmount}();
        }

        // Re-read balances after possible deposit
        uint midUserBal = c.getBalance(address(this));
        uint midCBalance = address(c).balance;

        // Track whether withdraw reverted
        bool withdrawReverted;
        if (doWithdraw) {
            try c.withdrawBalance() {
                withdrawReverted = false;
            } catch {
                withdrawReverted = true;
            }
        } else {
            withdrawReverted = false;
        }

        uint afterUserBal = c.getBalance(address(this));
        uint afterCBalance = address(c).balance;

        // General rule to assert:
        // If withdrawBalance was executed and did NOT revert, then the stored balance for this address is zero
        // and the contract's balance decreased by exactly the amount that was stored immediately before withdraw.
        // We express "amount stored immediately before withdraw" as midUserBal when doWithdraw==true,
        // otherwise the rule should not require anything about withdrawal.
        if (doWithdraw) {
            assert((withdrawReverted) || ((afterUserBal == 0) && (midCBalance - afterCBalance == midUserBal)));
        } else {
            // If not withdrawing, no state change required; assert that balances progressed consistently with deposit
            assert((midUserBal == beforeUserBal + depositAmount) && (midCBalance == beforeCBalance + depositAmount) && (afterUserBal == midUserBal) && (afterCBalance == midCBalance));
        }
    }

    // Allow this contract to receive Ether when c calls back on withdraw
    receive() external payable {}
}

