contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking an amount to deposit first and then attempting withdrawal
    function run(uint deposit) public payable {
        require(address(this).balance >= deposit);

        // record contract balance and recorded balance for this test contract before any actions
        uint beforeContractBal = address(c).balance;
        uint beforeRecorded = c.getBalance(address(this));

        // perform an addToBalance call on c sending `deposit` wei
        if (deposit > 0) {
            c.addToBalance{value: deposit}();
        } else {
            // still call without value to exercise no-op deposit
            c.addToBalance{value: 0}();
        }

        // recorded balance should have increased by deposit (this is allowed to rely on public getter)
        uint afterRecorded = c.getBalance(address(this));
        uint afterContractBal = address(c).balance;

        // attempt withdrawal, capturing whether it reverted
        bool reverted;
        uint midContractBal = afterContractBal;
        uint midRecorded = afterRecorded;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe final recorded and contract balances
        uint finalRecorded = c.getBalance(address(this));
        uint finalContractBal = address(c).balance;

        // If withdrawBalance did not revert, then:
        // - the recorded balance for this test contract must be zero
        // - the contract's balance must have decreased by exactly the amount that was recorded just before withdrawal
        // If it reverted, no guarantee (so assert allows either reverted==true or the invariants hold)
        assert(reverted == true || (finalRecorded == 0 && midContractBal - finalContractBal == midRecorded));
    }

    // accept ETH to allow deposit parameter to be forwarded
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: take no Ether as input because we will first
    // deposit an arbitrary amount into c on behalf of this contract by calling addToBalance
    // with value 'amount'. Then call withdrawBalance and check the invariant.
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // Make a deposit into c on behalf of this contract (msg.sender for c calls will be this contract)
        // We perform the deposit only if amount > 0 to exercise both zero and non-zero cases
        if (amount > 0) {
            c.addToBalance{value: amount}();
        }

        // Observe before-values
        uint256 beforeContractBal = address(c).balance;
        uint256 priorRecorded = c.getBalance(address(this));

        // Call withdraw and capture whether it reverted
        bool didRevert;
        try c.withdrawBalance() {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // Observe after-values (only via public surface)
        uint256 afterContractBal = address(c).balance;
        uint256 recordedAfter = c.getBalance(address(this));

        // General rule: if withdraw did not revert then the caller's recorded balance became zero
        // and the contract's balance decreased by exactly priorRecorded. If it reverted, no requirement
        // about balances is made here.
        assert(didRevert || (recordedAfter == 0 && beforeContractBal >= priorRecorded && afterContractBal + priorRecorded == beforeContractBal));
    }

    // Allow receiving ETH so the test contract can fund deposits
    receive() external payable {}
}

