contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: try to provoke a revert from withdrawBalance()
    // We take an amount to deposit first, then attempt withdrawal. We observe whether withdraw reverted
    // and assert that if it reverted then both the observed recorded balance and contract balance are unchanged.
    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        // initial observations
        uint beforeRecorded = c.getBalance(address(this));
        uint beforeContractBal = address(c).balance;

        // make a deposit if depositAmount > 0
        if (depositAmount > 0) {
            // send Ether to c as this contract (msg.sender for calls to c will be this test contract)
            c.addToBalance{value: depositAmount}();
        }

        // record values after deposit
        uint afterRecorded = c.getBalance(address(this));
        uint afterContractBal = address(c).balance;

        // Now attempt withdrawal and catch whether it reverted
        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint finalRecorded = c.getBalance(address(this));
        uint finalContractBal = address(c).balance;

        // General rule: if withdrawBalance() reverted then the recorded balance for this caller and contract balance did not change as a result of the attempted withdraw.
        // We express this by comparing the post-deposit values to the final values when reverted.
        assert(!reverted || (finalRecorded == afterRecorded && finalContractBal == afterContractBal));
    }

    // receive to accept refunds if any
    receive() external payable {}
}
